static FUNCTIONAL_GROUPS: [FunctionalGroup; 9] = [
    FunctionalGroup { name: "SALU", description: "Scalar ALU (SALU) instructions operate on values that are common to all work-items in the wave. These operations consist of 32-bit integer or floating-point arithmetic, and 32 or 64-bit bitwise operations, and they store results in scalar registers." },
    FunctionalGroup { name: "SMEM", description: "Scalar Memory (SMEM) instructions allow a shader program to load data from memory into scalar registers, making the data accessible to all work-items in the wave." },
    FunctionalGroup { name: "VALU", description: "Vector ALU (VALU) instructions perform arithmetic or logical operations on data for each of the wave's work-item and write results back to vector registers, scalar registers or the EXEC mask." },
    FunctionalGroup { name: "VMEM", description: "Vector-memory (VMEM) instructions transfer data to and from vector registers, making the data uniquely available for each work-item in the wave." },
    FunctionalGroup { name: "EXPORT", description: "Export instructions copy data from a VGPR to one of the export buffers (position, color, or Z)." },
    FunctionalGroup { name: "BRANCH", description: "Branch instructions allow programs to jump - direct or indirect - to an instruction to be executed next, conditionally or unconditionally." },
    FunctionalGroup { name: "MESSAGE", description: "Message instructions send a message to fixed function hardware or the host and can be used to request that a value be returned to the wave." },
    FunctionalGroup { name: "WAVE_CONTROL", description: "Wave control instructions control a wave's execution these include dependency, delay, scheduling, and wave termination operations." },
    FunctionalGroup { name: "TRAP", description: "Trap instructions transition into and out of the wave's trap handler" },
];
